"""Pull the body of the latest issue_read result for an issue out of a transcript, exactly as GitHub returned it.

Usage: python3 -I issue_body.py TRANSCRIPT ISSUE_NUMBER OUT_FILE
"""
import json, sys

path, number, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
names, body, where = {}, None, None
for n, line in enumerate(open(path, encoding="utf-8"), 1):
    try:
        event = json.loads(line)
    except ValueError:
        continue
    content = (event.get("message") or {}).get("content") if isinstance(event.get("message"), dict) else None
    if not isinstance(content, list):
        continue
    for block in content:
        if not isinstance(block, dict):
            continue
        if block.get("type") == "tool_use":
            names[block.get("id")] = (block.get("name"), block.get("input") or {})
        elif block.get("type") == "tool_result":
            name, params = names.get(block.get("tool_use_id"), (None, {}))
            if not (name or "").endswith("issue_read") or params.get("method") != "get" or params.get("issue_number") != number:
                continue
            result = block.get("content")
            if isinstance(result, list):
                result = "".join(b.get("text", "") for b in result if isinstance(b, dict))
            try:
                data = json.loads(result)
            except (TypeError, ValueError):
                continue
            if data.get("number") == number:
                body, where = data["body"], f"L{n} (updated_at {data.get('updated_at')})"

if body is None:
    sys.exit(f"no issue_read result for #{number}")
open(out, "w", encoding="utf-8", newline="").write(body)
print(f"#{number} body from {where}: {len(body)} chars, {body.count(chr(10)) + 1} lines, CR count {body.count(chr(13))} -> {out}")

